const express = require('express');
const apiRoutes = require('./routes');
const app = express();
app.use(express.json());
app.use('/api', apiRoutes);
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Listening on ${PORT}`));
module.exports = app;
